#!/usr/bin/env python3
"""Embed a binary file as a C array after checking its SHA-256."""

import argparse
import hashlib
import sys


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--symbol", required=True)
    parser.add_argument("--sha256", required=True)
    parser.add_argument("path")
    args = parser.parse_args()

    with open(args.path, "rb") as handle:
        data = handle.read()
    digest = hashlib.sha256(data).hexdigest()
    if digest != args.sha256.lower():
        print(f"{args.path}: SHA-256 {digest} does not match the pinned {args.sha256}",
              file=sys.stderr)
        return 1

    out = sys.stdout
    out.write("/* Generated by tools/gen_binary_c.py. Do not edit. */\n")
    out.write("#include <stddef.h>\n\n")
    out.write(f"const unsigned char {args.symbol}[] __attribute__((aligned(16))) = {{\n")
    for offset in range(0, len(data), 16):
        row = ", ".join(f"0x{b:02x}" for b in data[offset:offset + 16])
        out.write(f"  {row},\n")
    out.write("};\n")
    out.write(f"const size_t {args.symbol}_size = {len(data)};\n")
    out.write(f'const char {args.symbol}_sha256[] = "{digest}";\n')
    return 0


if __name__ == "__main__":
    sys.exit(main())
